static
void kernel_2mm(int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop

#if defined(__riscv_vector)
  /* First kernel: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j] */
  /* Reorder loops: i, k, j to enable vectorization over j with strided access on B */
  /* Zero tmp first */
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      tmp[i][j] = SCALAR_VAL(0.0);
    }
  }
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *A_i = A[i];
    DATA_TYPE *tmp_i = tmp[i];
    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE aik = A_i[k];
      DATA_TYPE aik_alpha = aik * alpha;
      DATA_TYPE *B_k = B[k];
      size_t vl;
      for (j = 0; j < _PB_NJ; ) {
        vl = __riscv_vsetvl_e64m1(_PB_NJ - j);
        vfloat64m1_t vtmp = __riscv_vle64_v_f64m1(&tmp_i[j], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B_k[j], vl);
        vtmp = __riscv_vfmacc_vf_f64m1(vtmp, aik_alpha, vb, vl);
        __riscv_vse64_v_f64m1(&tmp_i[j], vtmp, vl);
        j += vl;
      }
    }
  }
  /* Second kernel: D[i][j] = beta * D[i][j] + sum_k tmp[i][k] * C[k][j] */
  /* Reorder loops: i, k, j to enable vectorization over j with strided access on C */
  /* Apply beta scaling first */
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *D_i = D[i];
    size_t vl;
    for (j = 0; j < _PB_NL; ) {
      vl = __riscv_vsetvl_e64m1(_PB_NL - j);
      vfloat64m1_t vd = __riscv_vle64_v_f64m1(&D_i[j], vl);
      vd = __riscv_vfmul_vf_f64m1(vd, beta, vl);
      __riscv_vse64_v_f64m1(&D_i[j], vd, vl);
      j += vl;
    }
  }
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *tmp_i = tmp[i];
    DATA_TYPE *D_i = D[i];
    for (k = 0; k < _PB_NJ; k++) {
      DATA_TYPE tik = tmp_i[k];
      DATA_TYPE *C_k = C[k];
      size_t vl;
      for (j = 0; j < _PB_NL; ) {
        vl = __riscv_vsetvl_e64m1(_PB_NL - j);
        vfloat64m1_t vd = __riscv_vle64_v_f64m1(&D_i[j], vl);
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C_k[j], vl);
        vd = __riscv_vfmacc_vf_f64m1(vd, tik, vc, vl);
        __riscv_vse64_v_f64m1(&D_i[j], vd, vl);
        j += vl;
      }
    }
  }
#else
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	tmp[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  tmp[i][j] += alpha * A[i][k] * B[k][j];
      }
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	D[i][j] *= beta;
	for (k = 0; k < _PB_NJ; ++k)
	  D[i][j] += tmp[i][k] * C[k][j];
      }
#endif
#pragma endscop

}

static
void kernel_3mm(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(E,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(F,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl),
		DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j, k;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop

#if defined(__riscv_vector)
  // ---- First matrix multiply: E = A * B ----
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++) {
      E[i][j] = SCALAR_VAL(0.0);
    }
    size_t vl;
    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE aik = A[i][k];
      vfloat32m1_t vaik = __riscv_vfmv_v_f_f32m1((float)aik, 1);
      for (j = 0; j < _PB_NJ; j += vl) {
        vl = __riscv_vsetvl_e32m1(_PB_NJ - j);
        vfloat32m1_t vb = __riscv_vle32_v_f32m1((const float *)&B[k][j], vl);
        vfloat32m1_t ve = __riscv_vle32_v_f32m1((const float *)&E[i][j], vl);
        ve = __riscv_vfmacc_vv_f32m1(ve, vaik, vb, vl);
        __riscv_vse32_v_f32m1((float *)&E[i][j], ve, vl);
      }
    }
  }

  // ---- Second matrix multiply: F = C * D ----
  for (i = 0; i < _PB_NJ; i++) {
    for (j = 0; j < _PB_NL; j++) {
      F[i][j] = SCALAR_VAL(0.0);
    }
    size_t vl;
    for (k = 0; k < _PB_NM; k++) {
      DATA_TYPE cik = C[i][k];
      vfloat32m1_t vcik = __riscv_vfmv_v_f_f32m1((float)cik, 1);
      for (j = 0; j < _PB_NL; j += vl) {
        vl = __riscv_vsetvl_e32m1(_PB_NL - j);
        vfloat32m1_t vd = __riscv_vle32_v_f32m1((const float *)&D[k][j], vl);
        vfloat32m1_t vf = __riscv_vle32_v_f32m1((const float *)&F[i][j], vl);
        vf = __riscv_vfmacc_vv_f32m1(vf, vcik, vd, vl);
        __riscv_vse32_v_f32m1((float *)&F[i][j], vf, vl);
      }
    }
  }

  // ---- Third matrix multiply: G = E * F ----
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NL; j++) {
      G[i][j] = SCALAR_VAL(0.0);
    }
    size_t vl;
    for (k = 0; k < _PB_NJ; k++) {
      DATA_TYPE eik = E[i][k];
      vfloat32m1_t veik = __riscv_vfmv_v_f_f32m1((float)eik, 1);
      for (j = 0; j < _PB_NL; j += vl) {
        vl = __riscv_vsetvl_e32m1(_PB_NL - j);
        vfloat32m1_t vf = __riscv_vle32_v_f32m1((const float *)&F[k][j], vl);
        vfloat32m1_t vg = __riscv_vle32_v_f32m1((const float *)&G[i][j], vl);
        vg = __riscv_vfmacc_vv_f32m1(vg, veik, vf, vl);
        __riscv_vse32_v_f32m1((float *)&G[i][j], vg, vl);
      }
    }
  }
#else
  // ---- Scalar fallback ----
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NJ; j++)
      {
	E[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NK; ++k)
	  E[i][j] += A[i][k] * B[k][j];
      }

  for (i = 0; i < _PB_NJ; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	F[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NM; ++k)
	  F[i][j] += C[i][k] * D[k][j];
      }

  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      {
	G[i][j] = SCALAR_VAL(0.0);
	for (k = 0; k < _PB_NJ; ++k)
	  G[i][j] += E[i][k] * F[k][j];
      }
#endif
#pragma endscop

}

