#include <riscv_vector.h>
#endif

static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0)+mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0)+mul2;
  f = d;

  const DATA_TYPE one = SCALAR_VAL(1.0);
  const DATA_TYPE two = SCALAR_VAL(2.0);
  const DATA_TYPE zero = SCALAR_VAL(0.0);
  const int N_minus_1 = _PB_N - 1;
  const int N_minus_2 = _PB_N - 2;

  const DATA_TYPE neg_d = -d;
  const DATA_TYPE neg_f = -f;
  const DATA_TYPE neg_a = -a;
  const DATA_TYPE neg_c = -c;
  const DATA_TYPE one_plus_two_d = one + two * d;
  const DATA_TYPE one_plus_two_a = one + two * a;

 for (t=1; t<=_PB_TSTEPS; t++) {

    for (i=1; i<_PB_N-1; i++) {
      v[0][i] = one;
      p[i][0] = zero;
      q[i][0] = v[0][i];

      DATA_TYPE *p_i = p[i];
      DATA_TYPE *q_i = q[i];
      DATA_TYPE *u_i = u[i];
      DATA_TYPE *u_im1 = u[i-1];
      DATA_TYPE *u_ip1 = u[i+1];

      j = 1;
#if defined(__riscv_vector)
      size_t vl;
      for (; j <= N_minus_2; j += vl) {
        vl = __riscv_vsetvl_e64m1(N_minus_2 - j + 1);

        vfloat64m1_t p_prev = __riscv_vle64_v_f64m1(&p_i[j-1], vl);
        vfloat64m1_t q_prev = __riscv_vle64_v_f64m1(&q_i[j-1], vl);

        vfloat64m1_t denom = __riscv_vfmacc_vf_f64m1(__riscv_vfmv_v_f_f64m1(b, vl), a, p_prev, vl);

        vfloat64m1_t p_new = __riscv_vfdiv_vv_f64m1(__riscv_vfmv_v_f_f64m1(neg_c, vl), denom, vl);
        __riscv_vse64_v_f64m1(&p_i[j], p_new, vl);

        vfloat64m1_t u_im1_vec = __riscv_vle64_v_f64m1(&u_im1[j], vl);
        vfloat64m1_t u_i_vec = __riscv_vle64_v_f64m1(&u_i[j], vl);
        vfloat64m1_t u_ip1_vec = __riscv_vle64_v_f64m1(&u_ip1[j], vl);

        vfloat64m1_t num = __riscv_vfmul_vf_f64m1(u_im1_vec, neg_d, vl);
        num = __riscv_vfmacc_vf_f64m1(num, one_plus_two_d, u_i_vec, vl);
        num = __riscv_vfmacc_vf_f64m1(num, neg_f, u_ip1_vec, vl);
        num = __riscv_vfmacc_vf_f64m1(num, neg_a, q_prev, vl);

        vfloat64m1_t q_new = __riscv_vfdiv_vv_f64m1(num, denom, vl);
        __riscv_vse64_v_f64m1(&q_i[j], q_new, vl);
      }
#else
      for (; j < _PB_N-1; j++) {
        p[i][j] = -c / (a*p[i][j-1]+b);
        q[i][j] = (-d*u[j][i-1]+(one+two*d)*u[j][i] - f*u[j][i+1]-a*q[i][j-1])/(a*p[i][j-1]+b);
      }
#endif

      v[N_minus_1][i] = one;
      for (j=N_minus_2; j>=1; j--) {
        v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
      }
    }

    for (i=1; i<_PB_N-1; i++) {
      u[i][0] = one;
      p[i][0] = zero;
      q[i][0] = u[i][0];

      DATA_TYPE *p_i = p[i];
      DATA_TYPE *q_i = q[i];
      DATA_TYPE *v_i = v[i];
      DATA_TYPE *v_im1 = v[i-1];
      DATA_TYPE *v_ip1 = v[i+1];

      j = 1;
#if defined(__riscv_vector)
      size_t vl;
      for (; j <= N_minus_2; j += vl) {
        vl = __riscv_vsetvl_e64m1(N_minus_2 - j + 1);

        vfloat64m1_t p_prev = __riscv_vle64_v_f64m1(&p_i[j-1], vl);
        vfloat64m1_t q_prev = __riscv_vle64_v_f64m1(&q_i[j-1], vl);

        vfloat64m1_t denom = __riscv_vfmacc_vf_f64m1(__riscv_vfmv_v_f_f64m1(e, vl), d, p_prev, vl);

        vfloat64m1_t p_new = __riscv_vfdiv_vv_f64m1(__riscv_vfmv_v_f_f64m1(neg_f, vl), denom, vl);
        __riscv_vse64_v_f64m1(&p_i[j], p_new, vl);

        vfloat64m1_t v_im1_vec = __riscv_vle64_v_f64m1(&v_im1[j], vl);
        vfloat64m1_t v_i_vec = __riscv_vle64_v_f64m1(&v_i[j], vl);
        vfloat64m1_t v_ip1_vec = __riscv_vle64_v_f64m1(&v_ip1[j], vl);

        vfloat64m1_t num = __riscv_vfmul_vf_f64m1(v_im1_vec, neg_a, vl);
        num = __riscv_vfmacc_vf_f64m1(num, one_plus_two_a, v_i_vec, vl);
        num = __riscv_vfmacc_vf_f64m1(num, neg_c, v_ip1_vec, vl);
        num = __riscv_vfmacc_vf_f64m1(num, neg_d, q_prev, vl);

        vfloat64m1_t q_new = __riscv_vfdiv_vv_f64m1(num, denom, vl);
        __riscv_vse64_v_f64m1(&q_i[j], q_new, vl);
      }
#else
      for (; j < _PB_N-1; j++) {
        p[i][j] = -f / (d*p[i][j-1]+e);
        q[i][j] = (-a*v[i-1][j]+(one+two*a)*v[i][j] - c*v[i+1][j]-d*q[i][j-1])/(d*p[i][j-1]+e);
      }
#endif

      u[i][N_minus_1] = one;
      for (j=N_minus_2; j>=1; j--) {
        u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
      }
    }
  }
#pragma endscop
}

