#include <riscv_vector.h>
#endif

static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  // Initialize y to zero
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

#if defined(__riscv_vector)
  // RVV optimized version
  size_t vl;
  for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE tmp_val = SCALAR_VAL(0.0);
      j = 0;

      // Compute tmp[i] = sum(A[i][j] * x[j]) using RVV
      size_t n_vl = __riscv_vsetvl_e32m1(_PB_N);
      for (; j <= _PB_N - (int)n_vl; j += (int)n_vl)
        {
          vl = __riscv_vsetvl_e32m1(_PB_N - j);
          vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float *)&x[j], vl);
          vfloat32m1_t vA = __riscv_vle32_v_f32m1((const float *)&A[i][j], vl);
          vfloat32m1_t vmul = __riscv_vfmul_vv_f32m1(vA, vx, vl);
          vfloat32m1_t vsum = __riscv_vfredusum_vs_f32m1_f32m1(vmul, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
          tmp_val += __riscv_vfmv_f_s_f32m1_f32(vsum);
        }

      // Handle remaining elements
      for (; j < _PB_N; j++)
        tmp_val += A[i][j] * x[j];

      tmp[i] = tmp_val;

      // Update y[j] += A[i][j] * tmp[i] using RVV
      j = 0;
      DATA_TYPE t = tmp_val;
      n_vl = __riscv_vsetvl_e32m1(_PB_N);
      for (; j <= _PB_N - (int)n_vl; j += (int)n_vl)
        {
          vl = __riscv_vsetvl_e32m1(_PB_N - j);
          vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float *)&y[j], vl);
          vfloat32m1_t vA = __riscv_vle32_v_f32m1((const float *)&A[i][j], vl);
          vfloat32m1_t vtmp = __riscv_vfmv_v_f_f32m1((float)t, vl);
          vy = __riscv_vfmacc_vv_f32m1(vy, vtmp, vA, vl);
          __riscv_vse32_v_f32m1((float *)&y[j], vy, vl);
        }

      // Handle remaining elements
      for (; j < _PB_N; j++)
        y[j] += A[i][j] * t;
    }
#else
  // Scalar fallback
  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
        tmp[i] = tmp[i] + A[i][j] * x[j];
      for (j = 0; j < _PB_N; j++)
        y[j] = y[j] + A[i][j] * tmp[i];
    }
#endif
#pragma endscop
}

static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop
#if defined(__riscv_vector)
  size_t vl;
  for (i = 0; i < _PB_M; i += vl)
    {
      vl = __riscv_vsetvl_e32m1(_PB_M - i);
      vfloat32m1_t vec_zero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
      __riscv_vse32_v_f32m1((float *)&s[i], vec_zero, vl);
    }

  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE r_i = r[i];
      float r_f = (float)r_i;
      vfloat32m1_t vec_r = __riscv_vfmv_v_f_f32m1(r_f, 1);
      vfloat32m1_t vec_q_acc = __riscv_vfmv_v_f_f32m1(0.0f, 1);

      for (j = 0; j < _PB_M; j += vl)
        {
          vl = __riscv_vsetvl_e32m1(_PB_M - j);
          vfloat32m1_t vec_A = __riscv_vle32_v_f32m1((const float *)&A[i][j], vl);
          vfloat32m1_t vec_p = __riscv_vle32_v_f32m1((const float *)&p[j], vl);
          vfloat32m1_t vec_s = __riscv_vle32_v_f32m1((const float *)&s[j], vl);

          vec_s = __riscv_vfmacc_vf_f32m1(vec_s, r_f, vec_A, vl);
          __riscv_vse32_v_f32m1((float *)&s[j], vec_s, vl);

          vec_q_acc = __riscv_vfmacc_vv_f32m1(vec_q_acc, vec_A, vec_p, vl);
        }

      vfloat32m1_t vec_zero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
      vfloat32m1_t vec_sum = __riscv_vfredusum_vs_f32m1_f32m1(vec_q_acc, vec_zero, vl);
      q[i] = (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vec_sum);
    }
#else
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r[i] * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
#endif
#pragma endscop

}

