static
void kernel_cholesky(int n,
		     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

     for (j = 0; j < i; j++) {
        #if defined(__riscv_vector)
        DATA_TYPE sum = 0.0;
        size_t vl;
        for (k = 0; k < j; k += vl) {
           vl = __riscv_vsetvl_e64m1(j - k);
           vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][k], vl);
           vfloat64m1_t vec_b = __riscv_vle64_v_f64m1(&A[j][k], vl);
           vfloat64m1_t vec_mul = __riscv_vfmul_vv_f64m1(vec_a, vec_b, vl);
           vfloat64m1_t vec_partial = __riscv_vfredusum_vs_f64m1_f64m1(vec_mul, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
           sum += __riscv_vfmv_f_s_f64m1_f64(vec_partial);
        }
        A[i][j] -= sum;
        #else
        for (k = 0; k < j; k++) {
           A[i][j] -= A[i][k] * A[j][k];
        }
        #endif
        A[i][j] /= A[j][j];
     }

     #if defined(__riscv_vector)
     DATA_TYPE sum_sq = 0.0;
     size_t vl;
     for (k = 0; k < i; k += vl) {
        vl = __riscv_vsetvl_e64m1(i - k);
        vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][k], vl);
        vfloat64m1_t vec_sq = __riscv_vfmul_vv_f64m1(vec_a, vec_a, vl);
        vfloat64m1_t vec_partial = __riscv_vfredusum_vs_f64m1_f64m1(vec_sq, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
        sum_sq += __riscv_vfmv_f_s_f64m1_f64(vec_partial);
     }
     A[i][i] -= sum_sq;
     #else
     for (k = 0; k < i; k++) {
        A[i][i] -= A[i][k] * A[i][k];
     }
     #endif
     A[i][i] = SQRT_FUN(A[i][i]);
  }
#pragma endscop

}

