static
void kernel_covariance(int m, int n,
		       DATA_TYPE float_n,
		       DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
		       DATA_TYPE POLYBENCH_2D(cov,M,M,m,m),
		       DATA_TYPE POLYBENCH_1D(mean,M,m))
{
  int i, j, k;

#pragma scop
  for (j = 0; j < _PB_M; j++)
    {
      mean[j] = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_N; i++)
        mean[j] += data[i][j];
      mean[j] /= float_n;
    }

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      data[i][j] -= mean[j];

#if defined(__riscv_vector)
  size_t vl;
  for (i = 0; i < _PB_M; i++)
    {
      for (j = i; j < _PB_M; j++)
        {
          DATA_TYPE sum = SCALAR_VAL(0.0);
          vfloat64m1_t vsum = __riscv_vfmv_s_f_f64m1(0.0, 1);
          size_t k = 0;
          for (; k + 4 <= _PB_N; k += 4)
            {
              vl = __riscv_vsetvl_e64m1(_PB_N - k);
              vfloat64m1_t vd_i = __riscv_vle64_v_f64m1(&data[k][i], vl);
              vfloat64m1_t vd_j = __riscv_vle64_v_f64m1(&data[k][j], vl);
              vsum = __riscv_vfmacc_vv_f64m1(vsum, vd_i, vd_j, vl);
            }
          sum = __riscv_vfmv_f_s_f64m1_f64(vsum);
          for (; k < _PB_N; k++)
            sum += data[k][i] * data[k][j];
          cov[i][j] = sum / (float_n - SCALAR_VAL(1.0));
          cov[j][i] = cov[i][j];
        }
    }
#else
  for (i = 0; i < _PB_M; i++)
    for (j = i; j < _PB_M; j++)
      {
        cov[i][j] = SCALAR_VAL(0.0);
        for (k = 0; k < _PB_N; k++)
	  cov[i][j] += data[k][i] * data[k][j];
        cov[i][j] /= (float_n - SCALAR_VAL(1.0));
        cov[j][i] = cov[i][j];
      }
#endif
#pragma endscop

}

