void kernel_doitgen(int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

#pragma scop
  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++)  {
#if defined(__riscv_vector)
      size_t vl;
      for (p = 0; p < _PB_NP; p++) {
        sum[p] = SCALAR_VAL(0.0);
      }
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_val = A[r][q][s];
        float fa_val = (float)a_val;
        for (p = 0; p < _PB_NP; p += vl) {
          vl = __riscv_vsetvl_e32m1(_PB_NP - p);
          vfloat32m1_t va = __riscv_vfmv_v_f_f32m1(fa_val, vl);
          vfloat32m1_t vc4 = __riscv_vle32_v_f32m1((const float *)&C4[s][p], vl);
          vfloat32m1_t vsum = __riscv_vle32_v_f32m1((const float *)&sum[p], vl);
          vsum = __riscv_vfmacc_vv_f32m1(vsum, va, vc4, vl);
          __riscv_vse32_v_f32m1((float *)&sum[p], vsum, vl);
        }
      }
      for (p = 0; p < _PB_NP; p += vl) {
        vl = __riscv_vsetvl_e32m1(_PB_NP - p);
        vfloat32m1_t vsum = __riscv_vle32_v_f32m1((const float *)&sum[p], vl);
        __riscv_vse32_v_f32m1((float *)&A[r][q][p], vsum, vl);
      }
#else
      for (p = 0; p < _PB_NP; p++)  {
	sum[p] = SCALAR_VAL(0.0);
	for (s = 0; s < _PB_NP; s++)
	  sum[p] += A[r][q][s] * C4[s][p];
      }
      for (p = 0; p < _PB_NP; p++)
	A[r][q][p] = sum[p];
#endif
    }
#pragma endscop

}

