static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);
#if defined(__riscv_vector) && (DATA_TYPE_IS_FLOAT == 1)
   {
     size_t vl;
     i = 0;
     for (; i + 4 <= k; i += vl) {
       vl = __riscv_vsetvl_e32m1(k - i);
       vfloat32m1_t vr = __riscv_vle32_v_f32m1((const float *)&r[k - i - 1], vl);
       vfloat32m1_t vy = __riscv_vle32_v_f32m1((const float *)&y[i], vl);
       vfloat32m1_t vprod = __riscv_vfmul_vv_f32m1(vr, vy, vl);
       vfloat32m1_t vsum = __riscv_vfredusum_vs_f32m1_f32m1(vprod, __riscv_vfmv_v_f_f32m1(0.0f, vl), vl);
       sum += __riscv_vfmv_f_s_f32m1_f32(vsum);
     }
   }
   for (; i < k; i++) {
      sum += r[k-i-1]*y[i];
   }
#else
   for (i=0; i<k; i++) {
      sum += r[k-i-1]*y[i];
   }
#endif
   alpha = - (r[k] + sum)/beta;

#if defined(__riscv_vector) && (DATA_TYPE_IS_FLOAT == 1)
   {
     size_t vl;
     i = 0;
     for (; i + 4 <= k; i += vl) {
       vl = __riscv_vsetvl_e32m1(k - i);
       vfloat32m1_t vy1 = __riscv_vle32_v_f32m1((const float *)&y[i], vl);
       vfloat32m1_t vy2 = __riscv_vle32_v_f32m1((const float *)&y[k - i - 1], vl);
       vfloat32m1_t valpha = __riscv_vfmv_v_f_f32m1(alpha, vl);
       vfloat32m1_t vz = __riscv_vfmacc_vv_f32m1(vy1, valpha, vy2, vl);
       __riscv_vse32_v_f32m1((float *)&z[i], vz, vl);
     }
     for (; i < k; i++) {
       z[i] = y[i] + alpha*y[k-i-1];
     }
   }
   {
     size_t vl;
     i = 0;
     for (; i + 4 <= k; i += vl) {
       vl = __riscv_vsetvl_e32m1(k - i);
       vfloat32m1_t vz = __riscv_vle32_v_f32m1((const float *)&z[i], vl);
       __riscv_vse32_v_f32m1((float *)&y[i], vz, vl);
     }
     for (; i < k; i++) {
       y[i] = z[i];
     }
   }
#else
   for (i=0; i<k; i++) {
      z[i] = y[i] + alpha*y[k-i-1];
   }
   for (i=0; i<k; i++) {
     y[i] = z[i];
   }
#endif
   y[k] = alpha;
 }
#pragma endscop

}

