static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      /* ey[0][j] = _fict_[t] */
      {
        DATA_TYPE fval = _fict_[t];
#if defined(__riscv_vector)
        size_t vl;
        for (j = 0; j < _PB_NY; j += vl)
        {
          vl = __riscv_vsetvl_e64m1(_PB_NY - j);
          vfloat64m1_t vfval = __riscv_vfmv_v_f_f64m1(fval, vl);
          __riscv_vse64_v_f64m1(&ey[0][j], vfval, vl);
        }
#else
        for (j = 0; j < _PB_NY; j++)
          ey[0][j] = fval;
#endif
      }

      /* ey[i][j] = ey[i][j] - 0.5*(hz[i][j]-hz[i-1][j]) */
#if defined(__riscv_vector)
      {
        const DATA_TYPE half = SCALAR_VAL(0.5);
        size_t vl;
        for (i = 1; i < _PB_NX; i++)
        {
          DATA_TYPE *ey_i = ey[i];
          DATA_TYPE *hz_i = hz[i];
          DATA_TYPE *hz_im1 = hz[i-1];
          for (j = 0; j < _PB_NY; j += vl)
          {
            vl = __riscv_vsetvl_e64m1(_PB_NY - j);
            vfloat64m1_t vey = __riscv_vle64_v_f64m1(&ey_i[j], vl);
            vfloat64m1_t vhz_cur = __riscv_vle64_v_f64m1(&hz_i[j], vl);
            vfloat64m1_t vhz_prev = __riscv_vle64_v_f64m1(&hz_im1[j], vl);
            vfloat64m1_t vdiff = __riscv_vfsub_vv_f64m1(vhz_cur, vhz_prev, vl);
            vfloat64m1_t vscaled = __riscv_vfmul_vf_f64m1(vdiff, half, vl);
            vey = __riscv_vfsub_vv_f64m1(vey, vscaled, vl);
            __riscv_vse64_v_f64m1(&ey_i[j], vey, vl);
          }
        }
      }
#else
      for (i = 1; i < _PB_NX; i++)
        for (j = 0; j < _PB_NY; j++)
          ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
#endif

      /* ex[i][j] = ex[i][j] - 0.5*(hz[i][j]-hz[i][j-1]) */
#if defined(__riscv_vector)
      {
        const DATA_TYPE half = SCALAR_VAL(0.5);
        size_t vl;
        for (i = 0; i < _PB_NX; i++)
        {
          DATA_TYPE *ex_i = ex[i];
          DATA_TYPE *hz_i = hz[i];
          for (j = 1; j < _PB_NY; j += vl)
          {
            vl = __riscv_vsetvl_e64m1(_PB_NY - j);
            vfloat64m1_t vex = __riscv_vle64_v_f64m1(&ex_i[j], vl);
            vfloat64m1_t vhz_cur = __riscv_vle64_v_f64m1(&hz_i[j], vl);
            vfloat64m1_t vhz_prev = __riscv_vle64_v_f64m1(&hz_i[j-1], vl);
            vfloat64m1_t vdiff = __riscv_vfsub_vv_f64m1(vhz_cur, vhz_prev, vl);
            vfloat64m1_t vscaled = __riscv_vfmul_vf_f64m1(vdiff, half, vl);
            vex = __riscv_vfsub_vv_f64m1(vex, vscaled, vl);
            __riscv_vse64_v_f64m1(&ex_i[j], vex, vl);
          }
        }
      }
#else
      for (i = 0; i < _PB_NX; i++)
        for (j = 1; j < _PB_NY; j++)
          ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
#endif

      /* hz[i][j] = hz[i][j] - 0.7*(ex[i][j+1] - ex[i][j] + ey[i+1][j] - ey[i][j]) */
#if defined(__riscv_vector)
      {
        const DATA_TYPE factor = SCALAR_VAL(0.7);
        size_t vl;
        for (i = 0; i < _PB_NX - 1; i++)
        {
          DATA_TYPE *hz_i = hz[i];
          DATA_TYPE *ex_i = ex[i];
          DATA_TYPE *ey_i = ey[i];
          DATA_TYPE *ey_ip1 = ey[i+1];
          for (j = 0; j < _PB_NY - 1; j += vl)
          {
            vl = __riscv_vsetvl_e64m1(_PB_NY - 1 - j);
            vfloat64m1_t vhz = __riscv_vle64_v_f64m1(&hz_i[j], vl);
            vfloat64m1_t vex_jp1 = __riscv_vle64_v_f64m1(&ex_i[j+1], vl);
            vfloat64m1_t vex_j = __riscv_vle64_v_f64m1(&ex_i[j], vl);
            vfloat64m1_t vey_ip1_j = __riscv_vle64_v_f64m1(&ey_ip1[j], vl);
            vfloat64m1_t vey_i_j = __riscv_vle64_v_f64m1(&ey_i[j], vl);
            vfloat64m1_t vdiff_ex = __riscv_vfsub_vv_f64m1(vex_jp1, vex_j, vl);
            vfloat64m1_t vdiff_ey = __riscv_vfsub_vv_f64m1(vey_ip1_j, vey_i_j, vl);
            vfloat64m1_t vsum = __riscv_vfadd_vv_f64m1(vdiff_ex, vdiff_ey, vl);
            vfloat64m1_t vscaled = __riscv_vfmul_vf_f64m1(vsum, factor, vl);
            vhz = __riscv_vfsub_vv_f64m1(vhz, vscaled, vl);
            __riscv_vse64_v_f64m1(&hz_i[j], vhz, vl);
          }
        }
      }
#else
      for (i = 0; i < _PB_NX - 1; i++)
        for (j = 0; j < _PB_NY - 1; j++)
          hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
#endif
    }

#pragma endscop
}

