static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
#if defined(__riscv_vector)
      size_t vl;
      DATA_TYPE *path_k = path[k];

      for (i = 0; i < _PB_N; i++)
	{
	  DATA_TYPE path_ik = path[i][k];
	  DATA_TYPE *path_i = path[i];

	  j = 0;
	  for (; j <= _PB_N - 4; j += 4)
	    {
	      DATA_TYPE sum0 = path_ik + path_k[j];
	      DATA_TYPE sum1 = path_ik + path_k[j+1];
	      DATA_TYPE sum2 = path_ik + path_k[j+2];
	      DATA_TYPE sum3 = path_ik + path_k[j+3];

	      if (path_i[j] > sum0) path_i[j] = sum0;
	      if (path_i[j+1] > sum1) path_i[j+1] = sum1;
	      if (path_i[j+2] > sum2) path_i[j+2] = sum2;
	      if (path_i[j+3] > sum3) path_i[j+3] = sum3;
	    }
	  for (; j < _PB_N; j++)
	    {
	      DATA_TYPE sum = path_ik + path_k[j];
	      if (path_i[j] > sum) path_i[j] = sum;
	    }
	}
#else
      for(i = 0; i < _PB_N; i++)
	for (j = 0; j < _PB_N; j++)
	  path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	    path[i][j] : path[i][k] + path[k][j];
#endif
    }
#pragma endscop

}

