static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector)
  for (i = 0; i < _PB_NI; i++) {
    /* C[i][j] *= beta */
    size_t vl;
    for (j = 0; j < _PB_NJ; ) {
      vl = __riscv_vsetvl_e64m1(_PB_NJ - j);
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
      j += vl;
    }

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE aik = A[i][k];
      DATA_TYPE scaled_alpha = alpha * aik;
      for (j = 0; j < _PB_NJ; ) {
        vl = __riscv_vsetvl_e64m1(_PB_NJ - j);
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&B[k][j], vl);
        vc = __riscv_vfmacc_vf_f64m1(vc, scaled_alpha, vb, vl);
        __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
        j += vl;
      }
    }
  }
#else
  for (i = 0; i < _PB_NI; i++) {
    for (j = 0; j < _PB_NJ; j++)
	C[i][j] *= beta;
    for (k = 0; k < _PB_NK; k++) {
       for (j = 0; j < _PB_NJ; j++)
	  C[i][j] += alpha * A[i][k] * B[k][j];
    }
  }
#endif
#pragma endscop

}

