static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

#if defined(__riscv_vector)
  size_t vl;

  // First loop: A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE u1_i = u1[i];
    DATA_TYPE u2_i = u2[i];
    vfloat64m1_t vu1 = __riscv_vfmv_v_f_f64m1(u1_i, 1);
    vfloat64m1_t vu2 = __riscv_vfmv_v_f_f64m1(u2_i, 1);
    j = 0;
    for (; j + 8 <= _PB_N; j += 8) {
      vl = __riscv_vsetvl_e64m1(8);
      vfloat64m1_t vA = __riscv_vle64_v_f64m1(&A[i][j], vl);
      vfloat64m1_t vv1 = __riscv_vle64_v_f64m1(&v1[j], vl);
      vfloat64m1_t vv2 = __riscv_vle64_v_f64m1(&v2[j], vl);
      vA = __riscv_vfmacc_vv_f64m1(vA, vu1, vv1, vl);
      vA = __riscv_vfmacc_vv_f64m1(vA, vu2, vv2, vl);
      __riscv_vse64_v_f64m1(&A[i][j], vA, vl);
    }
    if (j < _PB_N) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j);
      vfloat64m1_t vA = __riscv_vle64_v_f64m1(&A[i][j], vl);
      vfloat64m1_t vv1 = __riscv_vle64_v_f64m1(&v1[j], vl);
      vfloat64m1_t vv2 = __riscv_vle64_v_f64m1(&v2[j], vl);
      vA = __riscv_vfmacc_vv_f64m1(vA, vu1, vv1, vl);
      vA = __riscv_vfmacc_vv_f64m1(vA, vu2, vv2, vl);
      __riscv_vse64_v_f64m1(&A[i][j], vA, vl);
    }
  }

  // Second loop: x[i] = x[i] + beta * A[j][i] * y[j]
  // Use strided load for A[j][i] and vector reduction
  {
    vfloat64m1_t vbeta = __riscv_vfmv_v_f_f64m1(beta, 1);
    for (i = 0; i < _PB_N; i++) {
      vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);
      j = 0;
      for (; j + 8 <= _PB_N; j += 8) {
        vl = __riscv_vsetvl_e64m1(8);
        vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
        vfloat64m1_t vA = __riscv_vlse64_v_f64m1(&A[j][i], sizeof(DATA_TYPE) * _PB_N, vl);
        vsum = __riscv_vfmacc_vv_f64m1(vsum, vA, vy, vl);
      }
      if (j < _PB_N) {
        vl = __riscv_vsetvl_e64m1(_PB_N - j);
        vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
        vfloat64m1_t vA = __riscv_vlse64_v_f64m1(&A[j][i], sizeof(DATA_TYPE) * _PB_N, vl);
        vsum = __riscv_vfmacc_vv_f64m1(vsum, vA, vy, vl);
      }
      vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vsum, __riscv_vfmv_v_f_f64m1(0.0, 1), __riscv_vsetvl_e64m1(8));
      DATA_TYPE dot = __riscv_vfmv_f_s_f64m1_f64(vred);
      x[i] = x[i] + beta * dot;
    }
  }

  // Third loop: x[i] = x[i] + z[i]
  for (i = 0; i < _PB_N; i += vl) {
    vl = __riscv_vsetvl_e64m1(_PB_N - i);
    vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[i], vl);
    vfloat64m1_t vz = __riscv_vle64_v_f64m1(&z[i], vl);
    vx = __riscv_vfadd_vv_f64m1(vx, vz, vl);
    __riscv_vse64_v_f64m1(&x[i], vx, vl);
  }

  // Fourth loop: w[i] = w[i] + alpha * A[i][j] * x[j]
  {
    vfloat64m1_t valpha = __riscv_vfmv_v_f_f64m1(alpha, 1);
    for (i = 0; i < _PB_N; i++) {
      vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);
      j = 0;
      for (; j + 8 <= _PB_N; j += 8) {
        vl = __riscv_vsetvl_e64m1(8);
        vfloat64m1_t vA = __riscv_vle64_v_f64m1(&A[i][j], vl);
        vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
        vsum = __riscv_vfmacc_vv_f64m1(vsum, vA, vx, vl);
      }
      if (j < _PB_N) {
        vl = __riscv_vsetvl_e64m1(_PB_N - j);
        vfloat64m1_t vA = __riscv_vle64_v_f64m1(&A[i][j], vl);
        vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
        vsum = __riscv_vfmacc_vv_f64m1(vsum, vA, vx, vl);
      }
      vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vsum, __riscv_vfmv_v_f_f64m1(0.0, 1), __riscv_vsetvl_e64m1(8));
      DATA_TYPE dot = __riscv_vfmv_f_s_f64m1_f64(vred);
      w[i] = w[i] + alpha * dot;
    }
  }
#else
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x[i] = x[i] + beta * A[j][i] * y[j];

  for (i = 0; i < _PB_N; i++)
    x[i] = x[i] + z[i];

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      w[i] = w[i] +  alpha * A[i][j] * x[j];
#endif

#pragma endscop
}

