#include <riscv_vector.h>
#endif

static
void kernel_gesummv(int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector)
  size_t vlmax = __riscv_vsetvlmax_e32m1();
  for (i = 0; i < _PB_N; i++)
    {
      vfloat32m1_t vtmp = __riscv_vfmv_v_f_f32m1(0.0f, vlmax);
      vfloat32m1_t vy = __riscv_vfmv_v_f_f32m1(0.0f, vlmax);
      for (j = 0; j < _PB_N; j += vlmax)
        {
          size_t vl = __riscv_vsetvl_e32m1(_PB_N - j);
          vfloat32m1_t vx = __riscv_vle32_v_f32m1((const float *)&x[j], vl);
          vfloat32m1_t va = __riscv_vle32_v_f32m1((const float *)&A[i][j], vl);
          vtmp = __riscv_vfmacc_vv_f32m1(vtmp, va, vx, vl);
          vfloat32m1_t vb = __riscv_vle32_v_f32m1((const float *)&B[i][j], vl);
          vy = __riscv_vfmacc_vv_f32m1(vy, vb, vx, vl);
        }
      vfloat32m1_t vsum_tmp = __riscv_vfredusum_vs_f32m1_f32m1(vtmp, __riscv_vfmv_v_f_f32m1(0.0f, vlmax), vlmax);
      vfloat32m1_t vsum_y = __riscv_vfredusum_vs_f32m1_f32m1(vy, __riscv_vfmv_v_f_f32m1(0.0f, vlmax), vlmax);
      float sum_tmp = __riscv_vfmv_f_s_f32m1_f32(vsum_tmp);
      float sum_y = __riscv_vfmv_f_s_f32m1_f32(vsum_y);
      tmp[i] = sum_tmp;
      y[i] = alpha * sum_tmp + beta * sum_y;
    }
#else
  for (i = 0; i < _PB_N; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);
      y[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
	{
	  tmp[i] = A[i][j] * x[j] + tmp[i];
	  y[i] = B[i][j] * x[j] + y[i];
	}
      y[i] = alpha * tmp[i] + beta * y[i];
    }
#endif
#pragma endscop

}

