static
void kernel_gramschmidt(int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      nrm = SCALAR_VAL(0.0);
#if defined(__riscv_vector)
      {
        size_t vl;
        vfloat64m1_t vec_sum = __riscv_vfmv_s_f_f64m1(0.0, 1);
        for (i = 0; i < _PB_M; i += vl) {
          vl = __riscv_vsetvl_e64m1(_PB_M - i);
          vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][k], vl);
          vec_sum = __riscv_vfmacc_vv_f64m1(vec_sum, vec_a, vec_a, vl);
        }
        vfloat64m1_t vec_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
        vec_sum = __riscv_vfredusum_vs_f64m1_f64m1(vec_sum, vec_zero, 1);
        nrm = __riscv_vfmv_f_s_f64m1_f64(vec_sum);
      }
#else
      for (i = 0; i < _PB_M; i++)
        nrm += A[i][k] * A[i][k];
#endif
      R[k][k] = SQRT_FUN(nrm);
#if defined(__riscv_vector)
      {
        size_t vl;
        DATA_TYPE rkk = R[k][k];
        for (i = 0; i < _PB_M; i += vl) {
          vl = __riscv_vsetvl_e64m1(_PB_M - i);
          vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][k], vl);
          vfloat64m1_t vec_q = __riscv_vfdiv_vf_f64m1(vec_a, rkk, vl);
          __riscv_vse64_v_f64m1(&Q[i][k], vec_q, vl);
        }
      }
#else
      for (i = 0; i < _PB_M; i++)
        Q[i][k] = A[i][k] / R[k][k];
#endif
      for (j = k + 1; j < _PB_N; j++)
	{
	  R[k][j] = SCALAR_VAL(0.0);
#if defined(__riscv_vector)
          {
            size_t vl;
            vfloat64m1_t vec_sum = __riscv_vfmv_s_f_f64m1(0.0, 1);
            for (i = 0; i < _PB_M; i += vl) {
              vl = __riscv_vsetvl_e64m1(_PB_M - i);
              vfloat64m1_t vec_q = __riscv_vle64_v_f64m1(&Q[i][k], vl);
              vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][j], vl);
              vec_sum = __riscv_vfmacc_vv_f64m1(vec_sum, vec_q, vec_a, vl);
            }
            vfloat64m1_t vec_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);
            vec_sum = __riscv_vfredusum_vs_f64m1_f64m1(vec_sum, vec_zero, 1);
            R[k][j] = __riscv_vfmv_f_s_f64m1_f64(vec_sum);
          }
#else
	  for (i = 0; i < _PB_M; i++)
	    R[k][j] += Q[i][k] * A[i][j];
#endif
#if defined(__riscv_vector)
          {
            size_t vl;
            DATA_TYPE rkj = R[k][j];
            for (i = 0; i < _PB_M; i += vl) {
              vl = __riscv_vsetvl_e64m1(_PB_M - i);
              vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][j], vl);
              vfloat64m1_t vec_q = __riscv_vle64_v_f64m1(&Q[i][k], vl);
              vec_a = __riscv_vfnmsac_vf_f64m1(vec_a, rkj, vec_q, vl);
              __riscv_vse64_v_f64m1(&A[i][j], vec_a, vl);
            }
          }
#else
	  for (i = 0; i < _PB_M; i++)
	    A[i][j] = A[i][j] - Q[i][k] * R[k][j];
#endif
	}
    }
#pragma endscop

}

