static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
    for (t = 1; t <= TSTEPS; t++) {
        for (i = 1; i < _PB_N-1; i++) {
            for (j = 1; j < _PB_N-1; j++) {
#if defined(__riscv_vector)
                size_t vl;
                for (k = 1; k < _PB_N-1; k += vl) {
                    vl = __riscv_vsetvl_e64m1(_PB_N - 1 - k);
                    vfloat64m1_t A_center = __riscv_vle64_v_f64m1(&A[i][j][k], vl);
                    vfloat64m1_t A_left   = __riscv_vle64_v_f64m1(&A[i][j][k-1], vl);
                    vfloat64m1_t A_right  = __riscv_vle64_v_f64m1(&A[i][j][k+1], vl);
                    vfloat64m1_t A_up     = __riscv_vle64_v_f64m1(&A[i][j+1][k], vl);
                    vfloat64m1_t A_down   = __riscv_vle64_v_f64m1(&A[i][j-1][k], vl);
                    vfloat64m1_t A_front  = __riscv_vle64_v_f64m1(&A[i+1][j][k], vl);
                    vfloat64m1_t A_back   = __riscv_vle64_v_f64m1(&A[i-1][j][k], vl);

                    vfloat64m1_t sum = __riscv_vfadd_vv_f64m1(A_left, A_right, vl);
                    sum = __riscv_vfadd_vv_f64m1(sum, A_up, vl);
                    sum = __riscv_vfadd_vv_f64m1(sum, A_down, vl);
                    sum = __riscv_vfadd_vv_f64m1(sum, A_front, vl);
                    sum = __riscv_vfadd_vv_f64m1(sum, A_back, vl);

                    vfloat64m1_t c6 = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(6.0), vl);
                    vfloat64m1_t term = __riscv_vfmul_vv_f64m1(c6, A_center, vl);
                    sum = __riscv_vfsub_vv_f64m1(sum, term, vl);

                    vfloat64m1_t c0_125 = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.125), vl);
                    vfloat64m1_t result = __riscv_vfmul_vv_f64m1(c0_125, sum, vl);
                    result = __riscv_vfadd_vv_f64m1(result, A_center, vl);

                    __riscv_vse64_v_f64m1(&B[i][j][k], result, vl);
                }
#else
                for (k = 1; k < _PB_N-1; k++) {
                    B[i][j][k] =   SCALAR_VAL(0.125) * (A[i+1][j][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i-1][j][k])
                                 + SCALAR_VAL(0.125) * (A[i][j+1][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j-1][k])
                                 + SCALAR_VAL(0.125) * (A[i][j][k+1] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j][k-1])
                                 + A[i][j][k];
                }
#endif
            }
        }
        for (i = 1; i < _PB_N-1; i++) {
           for (j = 1; j < _PB_N-1; j++) {
#if defined(__riscv_vector)
               size_t vl;
               for (k = 1; k < _PB_N-1; k += vl) {
                   vl = __riscv_vsetvl_e64m1(_PB_N - 1 - k);
                   vfloat64m1_t B_center = __riscv_vle64_v_f64m1(&B[i][j][k], vl);
                   vfloat64m1_t B_left   = __riscv_vle64_v_f64m1(&B[i][j][k-1], vl);
                   vfloat64m1_t B_right  = __riscv_vle64_v_f64m1(&B[i][j][k+1], vl);
                   vfloat64m1_t B_up     = __riscv_vle64_v_f64m1(&B[i][j+1][k], vl);
                   vfloat64m1_t B_down   = __riscv_vle64_v_f64m1(&B[i][j-1][k], vl);
                   vfloat64m1_t B_front  = __riscv_vle64_v_f64m1(&B[i+1][j][k], vl);
                   vfloat64m1_t B_back   = __riscv_vle64_v_f64m1(&B[i-1][j][k], vl);

                   vfloat64m1_t sum = __riscv_vfadd_vv_f64m1(B_left, B_right, vl);
                   sum = __riscv_vfadd_vv_f64m1(sum, B_up, vl);
                   sum = __riscv_vfadd_vv_f64m1(sum, B_down, vl);
                   sum = __riscv_vfadd_vv_f64m1(sum, B_front, vl);
                   sum = __riscv_vfadd_vv_f64m1(sum, B_back, vl);

                   vfloat64m1_t c6 = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(6.0), vl);
                   vfloat64m1_t term = __riscv_vfmul_vv_f64m1(c6, B_center, vl);
                   sum = __riscv_vfsub_vv_f64m1(sum, term, vl);

                   vfloat64m1_t c0_125 = __riscv_vfmv_v_f_f64m1(SCALAR_VAL(0.125), vl);
                   vfloat64m1_t result = __riscv_vfmul_vv_f64m1(c0_125, sum, vl);
                   result = __riscv_vfadd_vv_f64m1(result, B_center, vl);

                   __riscv_vse64_v_f64m1(&A[i][j][k], result, vl);
               }
#else
               for (k = 1; k < _PB_N-1; k++) {
                   A[i][j][k] =   SCALAR_VAL(0.125) * (B[i+1][j][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i-1][j][k])
                                + SCALAR_VAL(0.125) * (B[i][j+1][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j-1][k])
                                + SCALAR_VAL(0.125) * (B[i][j][k+1] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j][k-1])
                                + B[i][j][k];
               }
#endif
           }
       }
    }
#pragma endscop

}

static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop
#if defined(__riscv_vector)
  size_t vl;
  vfloat64m1_t vec_third, vec_A_prev, vec_A_curr, vec_A_next, vec_B_prev, vec_B_curr, vec_B_next, vec_sum, vec_result;
  double third = 0.33333;
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      // B[i] = 0.33333 * (A[i-1] + A[i] + A[i+1])
      i = 1;
      vec_third = __riscv_vfmv_v_f_f64m1(third, 1);
      for (; i <= _PB_N - 1 - 1; i += vl)
        {
          vl = __riscv_vsetvl_e64m1(_PB_N - 1 - i);
          vec_A_prev = __riscv_vle64_v_f64m1(&A[i-1], vl);
          vec_A_curr = __riscv_vle64_v_f64m1(&A[i], vl);
          vec_A_next = __riscv_vle64_v_f64m1(&A[i+1], vl);
          vec_sum = __riscv_vfadd_vv_f64m1(vec_A_prev, vec_A_curr, vl);
          vec_sum = __riscv_vfadd_vv_f64m1(vec_sum, vec_A_next, vl);
          vec_result = __riscv_vfmul_vv_f64m1(vec_sum, vec_third, vl);
          __riscv_vse64_v_f64m1(&B[i], vec_result, vl);
        }
      // A[i] = 0.33333 * (B[i-1] + B[i] + B[i+1])
      i = 1;
      for (; i <= _PB_N - 1 - 1; i += vl)
        {
          vl = __riscv_vsetvl_e64m1(_PB_N - 1 - i);
          vec_B_prev = __riscv_vle64_v_f64m1(&B[i-1], vl);
          vec_B_curr = __riscv_vle64_v_f64m1(&B[i], vl);
          vec_B_next = __riscv_vle64_v_f64m1(&B[i+1], vl);
          vec_sum = __riscv_vfadd_vv_f64m1(vec_B_prev, vec_B_curr, vl);
          vec_sum = __riscv_vfadd_vv_f64m1(vec_sum, vec_B_next, vl);
          vec_result = __riscv_vfmul_vv_f64m1(vec_sum, vec_third, vl);
          __riscv_vse64_v_f64m1(&A[i], vec_result, vl);
        }
    }
#else
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < _PB_N - 1; i++)
	B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
      for (i = 1; i < _PB_N - 1; i++)
	A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
    }
#endif
#pragma endscop

}

