static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < _PB_N - 1; i++)
	{
#if defined(__riscv_vector)
	  size_t vl;
	  for (j = 1; j < _PB_N - 1; j += vl)
	    {
	      vl = __riscv_vsetvl_e64m2((size_t)(_PB_N - 1 - j));
	      vfloat64m2_t va_center = __riscv_vle64_v_f64m2(&A[i][j], vl);
	      vfloat64m2_t va_left   = __riscv_vle64_v_f64m2(&A[i][j-1], vl);
	      vfloat64m2_t va_right  = __riscv_vle64_v_f64m2(&A[i][j+1], vl);
	      vfloat64m2_t va_up     = __riscv_vle64_v_f64m2(&A[i-1][j], vl);
	      vfloat64m2_t va_down   = __riscv_vle64_v_f64m2(&A[i+1][j], vl);

	      vfloat64m2_t vsum = __riscv_vfadd_vv_f64m2(va_center, va_left, vl);
	      vsum = __riscv_vfadd_vv_f64m2(vsum, va_right, vl);
	      vsum = __riscv_vfadd_vv_f64m2(vsum, va_up, vl);
	      vsum = __riscv_vfadd_vv_f64m2(vsum, va_down, vl);

	      vfloat64m2_t vscalar = __riscv_vfmv_v_f_f64m2(SCALAR_VAL(0.2), vl);
	      vfloat64m2_t vb = __riscv_vfmul_vv_f64m2(vsum, vscalar, vl);
	      __riscv_vse64_v_f64m2(&B[i][j], vb, vl);
	    }
#else
	  for (j = 1; j < _PB_N - 1; j++)
	    B[i][j] = SCALAR_VAL(0.2) * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
#endif
	}
      for (i = 1; i < _PB_N - 1; i++)
	{
#if defined(__riscv_vector)
	  size_t vl;
	  for (j = 1; j < _PB_N - 1; j += vl)
	    {
	      vl = __riscv_vsetvl_e64m2((size_t)(_PB_N - 1 - j));
	      vfloat64m2_t vb_center = __riscv_vle64_v_f64m2(&B[i][j], vl);
	      vfloat64m2_t vb_left   = __riscv_vle64_v_f64m2(&B[i][j-1], vl);
	      vfloat64m2_t vb_right  = __riscv_vle64_v_f64m2(&B[i][j+1], vl);
	      vfloat64m2_t vb_up     = __riscv_vle64_v_f64m2(&B[i-1][j], vl);
	      vfloat64m2_t vb_down   = __riscv_vle64_v_f64m2(&B[i+1][j], vl);

	      vfloat64m2_t vsum = __riscv_vfadd_vv_f64m2(vb_center, vb_left, vl);
	      vsum = __riscv_vfadd_vv_f64m2(vsum, vb_right, vl);
	      vsum = __riscv_vfadd_vv_f64m2(vsum, vb_up, vl);
	      vsum = __riscv_vfadd_vv_f64m2(vsum, vb_down, vl);

	      vfloat64m2_t vscalar = __riscv_vfmv_v_f_f64m2(SCALAR_VAL(0.2), vl);
	      vfloat64m2_t va = __riscv_vfmul_vv_f64m2(vsum, vscalar, vl);
	      __riscv_vse64_v_f64m2(&A[i][j], va, vl);
	    }
#else
	  for (j = 1; j < _PB_N - 1; j++)
	    A[i][j] = SCALAR_VAL(0.2) * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
#endif
	}
    }
#pragma endscop

}

