static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // First part: j < i
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = 0;
      #if defined(__riscv_vector)
      size_t vl;
      for (k = 0; k < j; k += vl) {
        vl = __riscv_vsetvl_e64m1(j - k);
        vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][k], vl);
        vfloat64m1_t vec_b = __riscv_vle64_v_f64m1(&A[k][j], vl);
        vfloat64m1_t vec_mul = __riscv_vfmul_vv_f64m1(vec_a, vec_b, vl);
        vfloat64m1_t vec_sum = __riscv_vfredusum_vs_f64m1_f64m1(vec_mul, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
        sum += __riscv_vfmv_f_s_f64m1_f64(vec_sum);
      }
      #else
      for (k = 0; k < j; k++) {
        sum += A[i][k] * A[k][j];
      }
      #endif
      A[i][j] -= sum;
      A[i][j] /= A[j][j];
    }
    // Second part: j >= i
    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = 0;
      #if defined(__riscv_vector)
      size_t vl;
      for (k = 0; k < i; k += vl) {
        vl = __riscv_vsetvl_e64m1(i - k);
        vfloat64m1_t vec_a = __riscv_vle64_v_f64m1(&A[i][k], vl);
        vfloat64m1_t vec_b = __riscv_vle64_v_f64m1(&A[k][j], vl);
        vfloat64m1_t vec_mul = __riscv_vfmul_vv_f64m1(vec_a, vec_b, vl);
        vfloat64m1_t vec_sum = __riscv_vfredusum_vs_f64m1_f64m1(vec_mul, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
        sum += __riscv_vfmv_f_s_f64m1_f64(vec_sum);
      }
      #else
      for (k = 0; k < i; k++) {
        sum += A[i][k] * A[k][j];
      }
      #endif
      A[i][j] -= sum;
    }
  }
#pragma endscop
}

