static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;

  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *A_i = A[i];
    for (j = 0; j < i; j++) {
       w = A_i[j];
#if defined(__riscv_vector)
       size_t vl;
       for (k = 0; k < j; ) {
           vl = __riscv_vsetvl_e64m1(j - k);
           vfloat64m1_t va = __riscv_vle64_v_f64m1(&A_i[k], vl);
           vfloat64m1_t vb = __riscv_vle64_v_f64m1(&A[k][j], vl);
           vfloat64m1_t vc = __riscv_vfmul_vv_f64m1(va, vb, vl);
           vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m1_f64m1(vc, __riscv_vfmv_s_f_f64m1(0.0, vl), vl);
           w -= __riscv_vfmv_f_s_f64m1_f64(vsum);
           k += vl;
       }
#else
       for (k = 0; k < j; k++) {
          w -= A_i[k] * A[k][j];
       }
#endif
       A_i[j] = w / A[j][j];
    }
    for (j = i; j < _PB_N; j++) {
       w = A_i[j];
#if defined(__riscv_vector)
       size_t vl;
       for (k = 0; k < i; ) {
           vl = __riscv_vsetvl_e64m1(i - k);
           vfloat64m1_t va = __riscv_vle64_v_f64m1(&A_i[k], vl);
           vfloat64m1_t vb = __riscv_vle64_v_f64m1(&A[k][j], vl);
           vfloat64m1_t vc = __riscv_vfmul_vv_f64m1(va, vb, vl);
           vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m1_f64m1(vc, __riscv_vfmv_s_f_f64m1(0.0, vl), vl);
           w -= __riscv_vfmv_f_s_f64m1_f64(vsum);
           k += vl;
       }
#else
       for (k = 0; k < i; k++) {
          w -= A_i[k] * A[k][j];
       }
#endif
       A_i[j] = w;
    }
  }

  for (i = 0; i < _PB_N; i++) {
     w = b[i];
     DATA_TYPE *A_i = A[i];
#if defined(__riscv_vector)
     size_t vl;
     for (j = 0; j < i; ) {
         vl = __riscv_vsetvl_e64m1(i - j);
         vfloat64m1_t va = __riscv_vle64_v_f64m1(&A_i[j], vl);
         vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
         vfloat64m1_t vc = __riscv_vfmul_vv_f64m1(va, vy, vl);
         vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m1_f64m1(vc, __riscv_vfmv_s_f_f64m1(0.0, vl), vl);
         w -= __riscv_vfmv_f_s_f64m1_f64(vsum);
         j += vl;
     }
#else
     for (j = 0; j < i; j++)
        w -= A_i[j] * y[j];
#endif
     y[i] = w;
  }

   for (i = _PB_N-1; i >=0; i--) {
     w = y[i];
     DATA_TYPE *A_i = A[i];
#if defined(__riscv_vector)
     size_t vl;
     for (j = i+1; j < _PB_N; ) {
         vl = __riscv_vsetvl_e64m1(_PB_N - j);
         vfloat64m1_t va = __riscv_vle64_v_f64m1(&A_i[j], vl);
         vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
         vfloat64m1_t vc = __riscv_vfmul_vv_f64m1(va, vx, vl);
         vfloat64m1_t vsum = __riscv_vfredusum_vs_f64m1_f64m1(vc, __riscv_vfmv_s_f_f64m1(0.0, vl), vl);
         w -= __riscv_vfmv_f_s_f64m1_f64(vsum);
         j += vl;
     }
#else
     for (j = i+1; j < _PB_N; j++)
        w -= A_i[j] * x[j];
#endif
     x[i] = w / A_i[i];
  }
#pragma endscop

}

