static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
#if defined(__riscv_vector)
  // First loop: x1[i] = x1[i] + A[i][j] * y_1[j]
  for (i = 0; i < _PB_N; i++) {
    size_t vl;
    vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);
    DATA_TYPE *A_row = A[i];
    for (j = 0; j < _PB_N; j += vl) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y_1[j], vl);
      vfloat64m1_t vA = __riscv_vle64_v_f64m1(&A_row[j], vl);
      vsum = __riscv_vfmacc_vv_f64m1(vsum, vA, vy, vl);
    }
    vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
    vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vsum, vzero, __riscv_vsetvl_e64m1(1));
    double sum = __riscv_vfmv_f_s_f64m1_f64(vred);
    x1[i] = x1[i] + sum;
  }

  // Second loop: x2[i] = x2[i] + A[j][i] * y_2[j]
  for (i = 0; i < _PB_N; i++) {
    size_t vl;
    vfloat64m1_t vsum = __riscv_vfmv_v_f_f64m1(0.0, 1);
    for (j = 0; j < _PB_N; j += vl) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j);
      vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y_2[j], vl);
      vfloat64m1_t vA = __riscv_vlse64_v_f64m1(&A[j][i], N * sizeof(DATA_TYPE), vl);
      vsum = __riscv_vfmacc_vv_f64m1(vsum, vA, vy, vl);
    }
    vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
    vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vsum, vzero, __riscv_vsetvl_e64m1(1));
    double sum = __riscv_vfmv_f_s_f64m1_f64(vred);
    x2[i] = x2[i] + sum;
  }
#else
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x1[i] = x1[i] + A[i][j] * y_1[j];
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_N; j++)
      x2[i] = x2[i] + A[j][i] * y_2[j];
#endif
#pragma endscop
}

static
void kernel_nussinov(int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop
 for (i = _PB_N-1; i >= 0; i--) {
  for (j=i+1; j<_PB_N; j++) {

   if (j-1>=0)
      table[i][j] = max_score(table[i][j], table[i][j-1]);
   if (i+1<_PB_N)
      table[i][j] = max_score(table[i][j], table[i+1][j]);

   if (j-1>=0 && i+1<_PB_N) {

     if (i<j-1)
        table[i][j] = max_score(table[i][j], table[i+1][j-1]+match(seq[i], seq[j]));
     else
        table[i][j] = max_score(table[i][j], table[i+1][j-1]);
   }

   for (k=i+1; k<j; k++) {
      table[i][j] = max_score(table[i][j], table[i][k] + table[k+1][j]);
   }
  }
 }
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_seidel_2d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t <= _PB_TSTEPS - 1; t++) {
    #if defined(__riscv_vector)
    for (i = 1; i <= _PB_N - 2; i++) {
      size_t vl;
      DATA_TYPE *row_prev = &A[i-1][0];
      DATA_TYPE *row_curr = &A[i][0];
      DATA_TYPE *row_next = &A[i+1][0];
      DATA_TYPE *row_out = &A[i][0];

      for (j = 1; j <= _PB_N - 2; ) {
        vl = __riscv_vsetvl_e64m2((size_t)(_PB_N - 2 - j + 1));

        vfloat64m2_t vprev_left  = __riscv_vle64_v_f64m2(&row_prev[j-1], vl);
        vfloat64m2_t vprev_mid   = __riscv_vle64_v_f64m2(&row_prev[j], vl);
        vfloat64m2_t vprev_right = __riscv_vle64_v_f64m2(&row_prev[j+1], vl);

        vfloat64m2_t vcurr_left  = __riscv_vle64_v_f64m2(&row_curr[j-1], vl);
        vfloat64m2_t vcurr_mid   = __riscv_vle64_v_f64m2(&row_curr[j], vl);
        vfloat64m2_t vcurr_right = __riscv_vle64_v_f64m2(&row_curr[j+1], vl);

        vfloat64m2_t vnext_left  = __riscv_vle64_v_f64m2(&row_next[j-1], vl);
        vfloat64m2_t vnext_mid   = __riscv_vle64_v_f64m2(&row_next[j], vl);
        vfloat64m2_t vnext_right = __riscv_vle64_v_f64m2(&row_next[j+1], vl);

        vfloat64m2_t vsum = __riscv_vfadd_vv_f64m2(vprev_left, vprev_mid, vl);
        vsum = __riscv_vfadd_vv_f64m2(vsum, vprev_right, vl);
        vsum = __riscv_vfadd_vv_f64m2(vsum, vcurr_left, vl);
        vsum = __riscv_vfadd_vv_f64m2(vsum, vcurr_mid, vl);
        vsum = __riscv_vfadd_vv_f64m2(vsum, vcurr_right, vl);
        vsum = __riscv_vfadd_vv_f64m2(vsum, vnext_left, vl);
        vsum = __riscv_vfadd_vv_f64m2(vsum, vnext_mid, vl);
        vsum = __riscv_vfadd_vv_f64m2(vsum, vnext_right, vl);

        vfloat64m2_t vdiv = __riscv_vfdiv_vf_f64m2(vsum, SCALAR_VAL(9.0), vl);
        __riscv_vse64_v_f64m2(&row_out[j], vdiv, vl);

        j += vl;
      }
    }
    #else
    for (i = 1; i <= _PB_N - 2; i++) {
      for (j = 1; j <= _PB_N - 2; j++) {
        A[i][j] = (A[i-1][j-1] + A[i-1][j] + A[i-1][j+1]
                   + A[i][j-1] + A[i][j] + A[i][j+1]
                   + A[i+1][j-1] + A[i+1][j] + A[i+1][j+1])/SCALAR_VAL(9.0);
      }
    }
    #endif
  }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

#pragma scop
   for (i = 0; i < _PB_M; i++) {
      DATA_TYPE *__restrict__ A_i = A[i];
      DATA_TYPE *__restrict__ B_i = B[i];
      DATA_TYPE A_ii = A_i[i];

      for (j = 0; j < _PB_N; j++ ) {
        DATA_TYPE B_ij = B_i[j];
        DATA_TYPE alpha_B_ij = alpha * B_ij;
        temp2 = 0;

#if defined(__riscv_vector)
        if (sizeof(DATA_TYPE) == sizeof(float)) {
          size_t vl;
          vfloat32m1_t vec_temp2 = __riscv_vfmv_s_f_f32m1(0.0f, 1);
          vfloat32m1_t vec_zero = __riscv_vfmv_v_f_f32m1(0.0f, 1);

          for (k = 0; k < i; k += vl) {
            vl = __riscv_vsetvl_e32m1(i - k);
            vfloat32m1_t vec_A_ik = __riscv_vle32_v_f32m1((const float *)&A_i[k], vl);
            vfloat32m1_t vec_B_kj = __riscv_vle32_v_f32m1((const float *)&B[k][j], vl);
            vfloat32m1_t vec_C_kj = __riscv_vle32_v_f32m1((const float *)&C[k][j], vl);

            vfloat32m1_t vec_update = __riscv_vfmul_vf_f32m1(vec_A_ik, (float)alpha_B_ij, vl);
            vec_C_kj = __riscv_vfadd_vv_f32m1(vec_C_kj, vec_update, vl);
            __riscv_vse32_v_f32m1((float *)&C[k][j], vec_C_kj, vl);

            vec_temp2 = __riscv_vfmacc_vv_f32m1(vec_temp2, vec_B_kj, vec_A_ik, vl);
          }

          vfloat32m1_t vec_sum = __riscv_vfredusum_vs_f32m1_f32m1(vec_temp2, vec_zero, __riscv_vsetvlmax_e32m1());
          temp2 = (DATA_TYPE)__riscv_vfmv_f_s_f32m1_f32(vec_sum);
        } else if (sizeof(DATA_TYPE) == sizeof(double)) {
          size_t vl;
          vfloat64m1_t vec_temp2 = __riscv_vfmv_s_f_f64m1(0.0, 1);
          vfloat64m1_t vec_zero = __riscv_vfmv_v_f_f64m1(0.0, 1);

          for (k = 0; k < i; k += vl) {
            vl = __riscv_vsetvl_e64m1(i - k);
            vfloat64m1_t vec_A_ik = __riscv_vle64_v_f64m1((const double *)&A_i[k], vl);
            vfloat64m1_t vec_B_kj = __riscv_vle64_v_f64m1((const double *)&B[k][j], vl);
            vfloat64m1_t vec_C_kj = __riscv_vle64_v_f64m1((const double *)&C[k][j], vl);

            vfloat64m1_t vec_update = __riscv_vfmul_vf_f64m1(vec_A_ik, (double)alpha_B_ij, vl);
            vec_C_kj = __riscv_vfadd_vv_f64m1(vec_C_kj, vec_update, vl);
            __riscv_vse64_v_f64m1((double *)&C[k][j], vec_C_kj, vl);

            vec_temp2 = __riscv_vfmacc_vv_f64m1(vec_temp2, vec_B_kj, vec_A_ik, vl);
          }

          vfloat64m1_t vec_sum = __riscv_vfredusum_vs_f64m1_f64m1(vec_temp2, vec_zero, __riscv_vsetvlmax_e64m1());
          temp2 = (DATA_TYPE)__riscv_vfmv_f_s_f64m1_f64(vec_sum);
        } else {
          for (k = 0; k < i; k++) {
             C[k][j] += alpha_B_ij * A_i[k];
             temp2 += B[k][j] * A_i[k];
          }
        }
#else
        for (k = 0; k < i; k++) {
           C[k][j] += alpha_B_ij * A_i[k];
           temp2 += B[k][j] * A_i[k];
        }
#endif

        C[i][j] = beta * C[i][j] + alpha_B_ij * A_ii + alpha * temp2;
      }
   }
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *c_row = &C[i][0];
    int len = i + 1;

    // Scale C[i][0..i] by beta
    #if defined(__riscv_vector)
    size_t vl;
    for (j = 0; j < len; j += vl) {
      vl = __riscv_vsetvl_e64m1(len - j);
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&c_row[j], vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(&c_row[j], vc, vl);
    }
    #else
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    #endif

    // Update C[i][0..i] with A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
    #if defined(__riscv_vector)
    // Precompute alpha * B[i][k] and alpha * A[i][k] for all k to reuse in vector loop
    DATA_TYPE alpha_b_ik[_PB_M];
    DATA_TYPE alpha_a_ik[_PB_M];
    for (k = 0; k < _PB_M; k++) {
      alpha_b_ik[k] = alpha * B[i][k];
      alpha_a_ik[k] = alpha * A[i][k];
    }

    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE *a_col_k = &A[0][k];
      DATA_TYPE *b_col_k = &B[0][k];
      DATA_TYPE ab = alpha_b_ik[k];
      DATA_TYPE aa = alpha_a_ik[k];

      size_t vl;
      for (j = 0; j < len; j += vl) {
        vl = __riscv_vsetvl_e64m1(len - j);
        vfloat64m1_t va = __riscv_vle64_v_f64m1(&a_col_k[j], vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(&b_col_k[j], vl);
        vfloat64m1_t vc = __riscv_vle64_v_f64m1(&c_row[j], vl);

        // term1 = A[j][k] * (alpha * B[i][k])
        vfloat64m1_t term1 = __riscv_vfmul_vf_f64m1(va, ab, vl);
        // term2 = B[j][k] * (alpha * A[i][k])
        vfloat64m1_t term2 = __riscv_vfmul_vf_f64m1(vb, aa, vl);
        // vc += term1 + term2
        vc = __riscv_vfmacc_vv_f64m1(vc, term1, term2, vl);

        __riscv_vse64_v_f64m1(&c_row[j], vc, vl);
      }
    }
    #else
    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE b_ik = B[i][k];
      DATA_TYPE a_ik = A[i][k];
      DATA_TYPE alpha_b_ik = alpha * b_ik;
      DATA_TYPE alpha_a_ik = alpha * a_ik;
      for (j = 0; j <= i; j++) {
        C[i][j] += A[j][k] * alpha_b_ik + B[j][k] * alpha_a_ik;
      }
    }
    #endif
  }
#pragma endscop
}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

#pragma scop
#if defined(__riscv_vector)
  for (i = 0; i < _PB_N; i++) {
    // Scale C[i][0..i] by beta using vector operations
    size_t vl;
    for (j = 0; j <= i; j += vl) {
      vl = __riscv_vsetvl_e64m1(i - j + 1);
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
    }

    // Accumulate alpha * A[i][k] * A[j][k] into C[i][j]
    for (k = 0; k < _PB_M; k++) {
      DATA_TYPE aik = alpha * A[i][k];
      if (aik != (DATA_TYPE)0) {
        for (j = 0; j <= i; j += vl) {
          vl = __riscv_vsetvl_e64m1(i - j + 1);
          vfloat64m1_t vc = __riscv_vle64_v_f64m1(&C[i][j], vl);
          vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[j][k], vl);
          vc = __riscv_vfmacc_vf_f64m1(vc, aik, va, vl);
          __riscv_vse64_v_f64m1(&C[i][j], vc, vl);
        }
      }
    }
  }
#else
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;
    for (k = 0; k < _PB_M; k++) {
      for (j = 0; j <= i; j++)
        C[i][j] += alpha * A[i][k] * A[j][k];
    }
  }
#endif
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      x[i] = b[i];
#if defined(__riscv_vector)
      size_t vl;
      vfloat64m1_t vL, vxj, vsum;
      double sum;
      j = 0;
      for (; j + 8 <= i; j += 8)
        {
          vl = __riscv_vsetvl_e64m1(8);
          vL = __riscv_vle64_v_f64m1(&L[i][j], vl);
          vxj = __riscv_vle64_v_f64m1(&x[j], vl);
          vsum = __riscv_vfmul_vv_f64m1(vL, vxj, vl);
          vfloat64m1_t vred = __riscv_vfredusum_vs_f64m1_f64m1(vsum, __riscv_vfmv_s_f_f64m1(0.0, vl), vl);
          sum = __riscv_vfmv_f_s_f64m1_f64(vred);
          x[i] -= sum;
        }
      for (; j < i; j++)
        x[i] -= L[i][j] * x[j];
#else
      for (j = 0; j < i; j++)
        x[i] -= L[i][j] * x[j];
#endif
      x[i] = x[i] / L[i][i];
    }
#pragma endscop

}

static
void kernel_trmm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

#pragma scop
#if defined(__riscv_vector)
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *B_i = B[i];
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE sum = B_i[j];
      size_t vl;
      for (k = i + 1; k < _PB_M; k += vl) {
        vl = __riscv_vsetvl_e64m1(_PB_M - k);
        vfloat64m1_t vec_A = __riscv_vle64_v_f64m1(&A[k][i], vl);
        vfloat64m1_t vec_B = __riscv_vle64_v_f64m1(&B[k][j], vl);
        vfloat64m1_t vec_mul = __riscv_vfmul_vv_f64m1(vec_A, vec_B, vl);
        vfloat64m1_t vec_sum = __riscv_vfredusum_vs_f64m1_f64m1(vec_mul, __riscv_vfmv_v_f_f64m1(0.0, vl), vl);
        sum += __riscv_vfmv_f_s_f64m1_f64(vec_sum);
      }
      B_i[j] = alpha * sum;
    }
  }
#else
  for (i = 0; i < _PB_M; i++)
     for (j = 0; j < _PB_N; j++) {
        for (k = i+1; k < _PB_M; k++)
           B[i][j] += A[k][i] * B[k][j];
        B[i][j] = alpha * B[i][j];
     }
#endif
#pragma endscop

}
